<script>
import {
  GlAlert,
  GlButton,
  GlForm,
  GlFormFields,
  GlFormPasswordInput,
  GlLink,
  GlLoadingIcon,
  GlSprintf,
} from '@gitlab/ui';
import {
  I18N_BUTTON_REGISTER,
  I18N_BUTTON_SETUP,
  I18N_BUTTON_TRY_AGAIN,
  I18N_DEVICE_NAME,
  I18N_DEVICE_NAME_DESCRIPTION,
  I18N_DEVICE_NAME_PLACEHOLDER,
  I18N_DEVICE_NAME_REQUIRED,
  I18N_ERROR_HTTP,
  I18N_ERROR_UNSUPPORTED_BROWSER,
  I18N_NOTICE,
  I18N_PASSWORD,
  I18N_PASSWORD_DESCRIPTION,
  I18N_PASSWORD_REQUIRED,
  I18N_STATUS_SUCCESS,
  I18N_STATUS_WAITING,
  STATE_ERROR,
  STATE_READY,
  STATE_SUCCESS,
  STATE_UNSUPPORTED,
  STATE_WAITING,
  WEBAUTHN_DOCUMENTATION_PATH,
  WEBAUTHN_REGISTER,
} from '~/authentication/webauthn/constants';
import WebAuthnError from '~/authentication/webauthn/error';
import {
  convertCreateParams,
  convertCreateResponse,
  isSecureContext,
  requiredNonBlank,
  supported,
} from '~/authentication/webauthn/util';
import csrf from '~/lib/utils/csrf';

export default {
  name: 'WebAuthnRegistration',
  components: {
    GlAlert,
    GlButton,
    GlForm,
    GlFormFields,
    GlFormPasswordInput,
    GlLink,
    GlLoadingIcon,
    GlSprintf,
  },
  formId: 'webauthn-registration-form',
  I18N_BUTTON_REGISTER,
  I18N_BUTTON_SETUP,
  I18N_BUTTON_TRY_AGAIN,
  I18N_DEVICE_NAME,
  I18N_DEVICE_NAME_DESCRIPTION,
  I18N_DEVICE_NAME_PLACEHOLDER,
  I18N_ERROR_HTTP,
  I18N_ERROR_UNSUPPORTED_BROWSER,
  I18N_NOTICE,
  I18N_PASSWORD,
  I18N_PASSWORD_DESCRIPTION,
  I18N_STATUS_SUCCESS,
  I18N_STATUS_WAITING,
  STATE_ERROR,
  STATE_READY,
  STATE_SUCCESS,
  STATE_UNSUPPORTED,
  STATE_WAITING,
  WEBAUTHN_DOCUMENTATION_PATH,
  inject: ['initialError', 'passwordRequired', 'targetPath'],
  data() {
    return {
      csrfToken: csrf.token,
      formFieldsValues: { deviceName: '', password: '' },
      state: STATE_UNSUPPORTED,
      errorMessage: this.initialError,
      credentials: null,
    };
  },
  computed: {
    fields() {
      const deviceNameField = {
        deviceName: {
          label: I18N_DEVICE_NAME,
          groupAttrs: { description: I18N_DEVICE_NAME_DESCRIPTION },
          validators: [requiredNonBlank(I18N_DEVICE_NAME_REQUIRED)],
          inputAttrs: {
            name: 'device_registration[name]',
            required: true,
            placeholder: I18N_DEVICE_NAME_PLACEHOLDER,
            'data-testid': 'device-name-input',
          },
        },
      };

      if (this.passwordRequired) {
        return {
          password: {
            label: I18N_PASSWORD,
            groupAttrs: { description: I18N_PASSWORD_DESCRIPTION },
            validators: [requiredNonBlank(I18N_PASSWORD_REQUIRED)],
          },
          ...deviceNameField,
        };
      }

      return deviceNameField;
    },
  },
  created() {
    if (this.errorMessage) {
      this.state = STATE_ERROR;
      return;
    }

    if (supported()) {
      this.state = STATE_READY;
      return;
    }

    this.errorMessage = isSecureContext() ? I18N_ERROR_UNSUPPORTED_BROWSER : I18N_ERROR_HTTP;
  },
  methods: {
    isCurrentState(state) {
      return this.state === state;
    },
    async onRegister() {
      this.state = STATE_WAITING;

      try {
        const credentials = await navigator.credentials.create({
          publicKey: convertCreateParams(gon.webauthn.options),
        });

        this.credentials = JSON.stringify(convertCreateResponse(credentials));
        this.state = STATE_SUCCESS;
      } catch (error) {
        this.errorMessage = new WebAuthnError(error, WEBAUTHN_REGISTER).message();
        this.state = STATE_ERROR;
      }
    },
    reset() {
      // We need to run this in the next tick because otherwise the cancel button doesn't collapse the form section.
      setTimeout(() => {
        this.state = STATE_READY;
        this.formFieldsValues = { deviceName: '', password: '' };
      });
    },
    onSubmit(event) {
      event.target.submit();
    },
  },
};
</script>

<template>
  <div class="gl-mb-5">
    <template v-if="isCurrentState($options.STATE_UNSUPPORTED)">
      <gl-alert variant="danger" :dismissible="false">
        {{ errorMessage }}
        <template #actions>
          <gl-button class="js-toggle-button">{{ __('Cancel') }}</gl-button>
        </template>
      </gl-alert>
    </template>

    <template v-else-if="isCurrentState($options.STATE_READY)">
      <gl-button variant="confirm" @click="onRegister">{{ $options.I18N_BUTTON_SETUP }}</gl-button>
      <gl-button class="js-toggle-button">{{ __('Cancel') }}</gl-button>
    </template>

    <template v-else-if="isCurrentState($options.STATE_WAITING)">
      <gl-alert :dismissible="false">
        {{ $options.I18N_STATUS_WAITING }}
        <gl-loading-icon size="lg" class="gl-p-4" />
        <template #actions>
          <gl-button class="js-toggle-button" @click="reset">{{ __('Cancel') }}</gl-button>
        </template>
      </gl-alert>
    </template>

    <template v-else-if="isCurrentState($options.STATE_SUCCESS)">
      <p>{{ $options.I18N_STATUS_SUCCESS }}</p>
      <gl-alert :dismissible="false" class="gl-mb-5">
        <gl-sprintf :message="$options.I18N_NOTICE">
          <template #link="{ content }">
            <gl-link :href="$options.WEBAUTHN_DOCUMENTATION_PATH" target="_blank">{{
              content
            }}</gl-link>
          </template>
        </gl-sprintf>
      </gl-alert>

      <gl-form
        :id="$options.formId"
        method="post"
        :action="targetPath"
        novalidate
        data-testid="create-webauthn"
      >
        <gl-form-fields
          v-model="formFieldsValues"
          :form-id="$options.formId"
          :fields="fields"
          :validate-on-blur="false"
          @submit="onSubmit"
        >
          <template #input(password)="{ id, validation, value, input }">
            <gl-form-password-input
              :id="id"
              :value="value"
              :state="validation.state"
              name="current_password"
              required
              autocomplete="current-password"
              data-testid="current-password-input"
              @input="input"
            />
          </template>
        </gl-form-fields>

        <input type="hidden" name="device_registration[device_response]" :value="credentials" />
        <input :value="csrfToken" type="hidden" name="authenticity_token" />

        <div class="gl-flex gl-gap-3">
          <gl-button type="submit" variant="confirm">{{ $options.I18N_BUTTON_REGISTER }}</gl-button>
          <gl-button class="js-toggle-button" @click="reset">{{ __('Cancel') }}</gl-button>
        </div>
      </gl-form>
    </template>

    <template v-else-if="isCurrentState($options.STATE_ERROR)">
      <gl-alert variant="danger" :dismissible="false">
        {{ errorMessage }}
        <template #actions>
          <div class="gl-flex gl-gap-3">
            <gl-button variant="confirm" @click="onRegister">{{
              $options.I18N_BUTTON_TRY_AGAIN
            }}</gl-button>
            <gl-button class="js-toggle-button" @click="reset">{{ __('Cancel') }}</gl-button>
          </div>
        </template>
      </gl-alert>
    </template>
  </div>
</template>
